"""Local, source-first inspector for untrusted machine annotations."""
import json
from .evidence_reader import AXES


def page():
    return HTML.replace('__AXES__', json.dumps({a: list(v) for a, v in AXES.items()}))


HTML = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Agere · Evidence reader</title><style>
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#10151b;color:#ebf1f5}
*{box-sizing:border-box}body{margin:0}main{max-width:1200px;margin:auto;padding:40px 24px}header{border-bottom:1px solid #35404b;padding-bottom:28px}small,.muted{color:#a4b2bf}h1{font-weight:500;font-size:42px;letter-spacing:-1.5px;margin:12px 0}p{line-height:1.55;max-width:850px}a{color:#a4ddd5}.tag{font:12px ui-monospace,monospace;letter-spacing:2px;color:#8fd8c8}
.stats{display:flex;gap:30px;flex-wrap:wrap;margin:25px 0}.stats b{font-size:26px;font-weight:500;display:block}.controls{display:flex;flex-wrap:wrap;align-items:end;gap:12px;background:#19212a;padding:20px;border-radius:12px;margin:24px 0}label{display:grid;gap:6px;font-size:12px;color:#aab9c8}select,input,button{border:1px solid #475565;border-radius:6px;background:#111a22;color:#edf5f9;padding:11px;font:inherit;min-height:42px}input{width:200px}button{cursor:pointer;background:#24685d}button:disabled{opacity:.45;cursor:default}.row{border-top:1px solid #35404b;padding:26px 0}.rowhead{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.pid{font-family:ui-monospace,monospace;color:#9edbce}.axes{display:flex;flex-wrap:wrap;gap:10px;margin:15px 0}.pill{background:#23313d;border:1px solid #405360;padding:7px 10px;border-radius:6px;font-size:13px}.pill small{display:block;font-size:10px;text-transform:uppercase;letter-spacing:1px;margin-bottom:3px}pre{white-space:pre-wrap;word-break:break-word;line-height:1.65;font:15px/1.65 ui-monospace,monospace;background:#19212a;border-radius:8px;padding:20px}mark{background:#b6e5d9;color:#102920;padding:1px 3px}details{color:#b4c3cc;margin:14px 0}summary{cursor:pointer}details pre{font-size:12px}.note{color:#d1bd94;font-size:13px}.nav{display:flex;align-items:center;gap:18px;margin:20px 0}#status{min-height:24px}footer{border-top:1px solid #35404b;margin-top:30px;padding-top:20px;color:#a4b2bf;font-size:13px}
</style><main><header><div class="tag">AGERE / EVIDENCE READER</div><h1>What does the record actually say?</h1><p>Inspect the learned reader’s interpretation of synthetic chart text. Who it concerns, whether it is asserted, when it applies, and the kind of evidence stay separate.</p><p class="note">Research annotations · All outputs require review · These filters do not establish care gaps or patient eligibility.</p><a href="/">Back to clinical workflow review</a> · <a id="explore-link" href="/explore" hidden>Compare recorded evidence</a></header>
<div class="stats" id="stats"></div><p id="validation" class="note"></p><form id="filters" class="controls"><label>Patient ID<input id="patient" placeholder="Any patient" autocomplete="off"></label><button type="submit">Inspect evidence</button></form><p id="status" role="status" aria-live="polite"></p><div id="rows"></div><div class="nav"><button id="prev">Previous</button><span id="page"></span><button id="next">Next</button></div><footer>“Current” is relative to the source account. A medication order is not proof of taking it; a records request is not proof of a completed visit. Evidence counts are annotation occurrences, not patient prevalence.</footer></main>
<script>
const axes=__AXES__;let offset=0,total=0;const size=15;
const $=id=>document.getElementById(id), human=s=>s.replaceAll('_',' ');
for(const [axis,values] of Object.entries(axes)){const label=document.createElement('label');label.textContent=human(axis);const select=document.createElement('select');select.id=axis;select.add(new Option('Any '+axis,''));for(const value of values)select.add(new Option(human(value),value));label.append(select);$('filters').insertBefore(label,$('filters').lastElementChild)}
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el}
async function load(){const params=new URLSearchParams({offset:String(offset),limit:String(size)});for(const name of ['patient',...Object.keys(axes),...($('priority')?['priority']:[])])if($(name).value)params.set(name,$(name).value);$('status').textContent='Reading source-bound annotations…';try{const response=await fetch('/api/annotations?'+params);if(!response.ok)throw Error('Annotations unavailable ('+response.status+')');const data=await response.json();total=data.total_bindings;$('rows').replaceChildren();for(const row of data.rows){const box=node('article',undefined,'row');const head=node('div',undefined,'rowhead');head.append(node('span',row.patient_id,'pid'),node('span',row.input.concept));box.append(head);const tags=node('div',undefined,'axes');for(const [a,v] of Object.entries(row.annotation.axes)){const pill=node('div',undefined,'pill');pill.append(node('small',a),node('span',human(v.label)));tags.append(pill)}box.append(tags);if(row.annotation.review_routing){const route=row.annotation.review_routing;box.append(node('p','Review route: '+human(route.priority),'note'));for(const reason of route.reasons)box.append(node('p',reason.detail,'muted'))}const text=node('pre');const x=row.input;text.append(document.createTextNode((x.prefix_omitted?'[… ] ':'')+x.text.slice(0,x.target_start)),node('mark',x.text.slice(x.target_start,x.target_end)),document.createTextNode(x.text.slice(x.target_end)+(x.suffix_omitted?' […]':'')));box.append(text,node('p',row.source.source_table+' · '+row.source.field+' · source event '+row.source.event_date+' · available '+row.source.available_date,'muted'));const detail=node('details');detail.append(node('summary','Exact source and model provenance'),node('pre',JSON.stringify({source:row.source,window_start:row.window_start,window_end:row.window_end,model_identity:row.annotation.model_identity,reader_scope:row.annotation.scope,scope_applies_to_axes:row.scope_applies_to_axes,consistency_issues:row.annotation.consistency_issues,alternate_axes:row.annotation.alternate_axes,review_routing:row.annotation.review_routing},null,2)));box.append(detail,node('p',row.annotation.limitations.join(' · '),'note'));$('rows').append(box)}$('status').textContent=total.toLocaleString()+' annotation occurrences match these filters. All are unvalidated model proposals.';$('page').textContent=total?`${offset+1}–${Math.min(offset+size,total)} of ${total.toLocaleString()}`:'No matches';$('prev').disabled=offset===0;$('next').disabled=offset+size>=total}catch(error){$('status').textContent=error.message}}
$('filters').addEventListener('submit',e=>{e.preventDefault();offset=0;load()});$('prev').onclick=()=>{offset=Math.max(0,offset-size);load()};$('next').onclick=()=>{offset+=size;load()};
fetch('/api/reader').then(r=>{if(!r.ok)throw Error('Reader run unavailable');return r.json()}).then(r=>{if(r.evidence_queries_available)$('explore-link').hidden=false;for(const [name,value] of [['Synthetic patients',r.counts.patients],['Text annotations',r.counts.annotation_bindings],['Paid calls for this pass',r.new_paid_api_calls],['Clinical decisions changed',r.clinical_decisions_changed]]){const el=node('div');el.append(node('b',Number(value).toLocaleString()),node('small',name));$('stats').append(el)}if(r.review_routing){const label=node('label','Review priority');const select=document.createElement('select');select.id='priority';select.add(new Option('Any review priority',''));for(const key of Object.keys(r.review_routing.priorities))select.add(new Option(human(key),key));label.append(select);$('filters').insertBefore(label,$('filters').lastElementChild)}if(r.transfer_diagnostic){const d=r.transfer_diagnostic,m=d.metrics.relation;$('validation').textContent=`Transfer diagnostic: the local reader matched teacher-consensus evidence relations in ${m.local_matches_teacher_consensus} of ${m.teacher_agreement_examples} agreed cases, from ${d.examples} synthetic excerpts. ${d.scope || ""} Substantial interpretation errors remain. Use this inspector to investigate failures, not to identify actionable care gaps.`}}).catch(e=>$('status').textContent=e.message);load();
</script></html>'''
